import{z as i,x as b,o as n,c as p,q as l,j as E,D as r,d as o,s,S as m,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Jamba 注意力-SSM 混合","description":"","frontmatter":{"title":"Jamba 注意力-SSM 混合","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/jamba.md","filePath":"llm/jamba.md","lastUpdated":1791063341000}'),M={name:"llm/jamba.md"};function B(d,a,A,f,h,S){const t=b("Mermaid");return n(),p("div",null,[a[2]||(a[2]=l('<h1 id="jamba-注意力-ssm-混合" tabindex="-1">Jamba 注意力-SSM 混合 <a class="header-anchor" href="#jamba-注意力-ssm-混合" aria-label="Permalink to &quot;Jamba 注意力-SSM 混合&quot;">​</a></h1><div class="epigraph"><p>少数 Transformer 层提供精确检索，多数 Mamba 层提供线性扫描；再在前馈里插 MoE。</p><footer>Lieber 等，Jamba，AI21，2024</footer></div><p><a href="/llm/griffin-hybrid">上一课</a>把全局 softmax 换成门控线性 RNN，精确匹配留在滑窗：循环混合可训练，精确的长程随机访问并不包含在这条路里。Griffin 按范围切，删掉的是全局注意力。缺口是按深度切——哪些层必须是全序列注意力，哪些层可以是 Mamba，前馈要不要 MoE。Jamba 用周期交错回答：注意力间隔决定 KV 预算，Mamba 层数决定扫描占比，专家层数决定激活参数。本课写这张层间混合图，不重写 RG-LRU 与窗口的分工。交错在预训练里钉死之后，几乎不能当推理开关用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mamba 把序列层做成线性时间和常数状态，但纯 SSM 堆叠在 in-context 学习、精确拷贝和某些推理格式上，往往落后于同规模 Transformer。注意力的 KV 表太贵，却是目前最可靠的随机访问记忆。两边的短板对称：全注意力付不起长上下文的缓存；全 Mamba 付不起「从任意位置取回一个 token」的精度。</p><p><span class="marginnote">直觉类比：Mamba 的常数状态像一本只有固定页数的笔记本——读再长的文章也只往这几页上摘要更新，好处是「笔记永不增厚」，坏处是三页前的原话被覆盖后就找不回来；注意力则像把整本书逐字复印存档，随时翻回原文，代价是复印纸（KV）随页数线性堆高。</span></p><p>Jamba 的问题不是再发明一种序列算子，而是<strong>在现有算子之间做层间交错</strong>：哪些层必须是注意力，哪些层可以是 Mamba，前馈要不要做成 MoE。目标是一张能在长上下文下部署的稠密–稀疏混合图，而不是理论上更纯的模型。</p><p><span class="marginnote">AI21 的 Jamba 是工程混合，层比、MoE 周期、注意力间隔都是超参，不是从第一性原理推出来的唯一解。</span></p><h3 id="单层替换解决不了检索" tabindex="-1">单层替换解决不了检索 <a class="header-anchor" href="#单层替换解决不了检索" aria-label="Permalink to &quot;单层替换解决不了检索&quot;">​</a></h3><p>把 Transformer 的每一层注意力换成 Mamba，得到的是纯 SSM 语言模型。长程压缩在，精确检索弱。把每一层都留成注意力，KV 随长度线性涨，百万 token 上下文在推理侧先被缓存打死。需要的是在深度方向上<strong>稀疏散布</strong>注意力，让大多数深度走 SSM。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Jamba 的骨架是重复的「混合块」。块内按固定周期排列：</p><ul><li>多数层：Mamba 序列混合 + 稠密或稀疏 MLP；</li><li>每隔 \\(l\\) 层：插入一层标准的因果 Transformer 注意力（带 KV），再接 MLP；</li><li>每隔 \\(e\\) 层：把 MLP 换成 MoE，路由到专家子集。</li></ul><p>注意力层是<strong>全序列</strong>的，不是 Griffin 那种滑动窗口。SSM 层用 Mamba 的选择性扫描。两者在残差流上交替，而不是在同一层里并联。MoE 不参与序列混合的选择，只放大前馈容量、压低每 token 激活参数。</p><h3 id="交错的周期" tabindex="-1">交错的周期 <a class="header-anchor" href="#交错的周期" aria-label="Permalink to &quot;交错的周期&quot;">​</a></h3><p>设总层数为 \\(L\\)。若每 \\(l\\) 层出现一次注意力，则注意力层数约为 \\(L/l\\)，KV 缓存按这个比例缩小。\\(l=1\\) 退回 Transformer；\\(l \\to L\\) 退回几乎纯 Mamba。Jamba 的实验落在中间：足够密的注意力以维持 in-context 与检索，足够稀以让长上下文的缓存可部署。</p><p>MoE 周期 \\(e\\) 独立于 \\(l\\)。序列层的线性时间与专家层的稀疏激活正交：前者管长度，后者管参数。把两者绑在同一层也可以，但论文把它们拆开，便于分别消融。</p><h3 id="仍是因果语言模型" tabindex="-1">仍是因果语言模型 <a class="header-anchor" href="#仍是因果语言模型" aria-label="Permalink to &quot;仍是因果语言模型&quot;">​</a></h3><p>位置、词嵌入、输出头与常规 Decoder-only Transformer 同类。变的是中间的序列混合器。注意力层使用和普通 Transformer 相同的 QKV 与因果掩码；Mamba 层使用选择性 SSM。没有新的位置编码理论，也没有新的路由理论——Jamba 是<strong>组装</strong>，组装的对象已经在各自论文里成立。</p>',19)),(n(),E(m,null,{default:r(()=>[s(t,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20TD%0A%20%20In%5B%22%E6%AE%8B%E5%B7%AE%E6%B5%81%22%5D%20--%3E%20M1%5B%22Mamba%20%E5%B1%82%22%5D%0A%20%20M1%20--%3E%20M2%5B%22Mamba%20%E5%B1%82%22%5D%0A%20%20M2%20--%3E%20Attn%5B%22Transformer%20%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%B1%82%22%5D%0A%20%20Attn%20--%3E%20MoE%5B%22MoE%20%E5%89%8D%E9%A6%88%22%5D%0A%20%20MoE%20--%3E%20Out%5B%22%E4%B8%8B%E4%B8%80%E5%9D%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("h3",{id:"注意力层在混合里实际做什么",tabindex:"-1"},[o("注意力层在混合里实际做什么 "),e("a",{class:"header-anchor",href:"#注意力层在混合里实际做什么","aria-label":'Permalink to "注意力层在混合里实际做什么"'},"​")],-1)),a[5]||(a[5]=e("p",null,"稀疏的全序列注意力提供全局的、可寻址的记忆。In-context 的示范、远处的约束、需要精确对齐的格式，由这些层完成匹配。因为层数少，KV 总量约为纯 Transformer 的 \\(1/l\\)。对长上下文推理，这是 Jamba 可落地的直接原因。",-1)),(n(),E(m,null,{default:r(()=>[s(t,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E9%97%B4%E9%9A%94%20l%22%5D%20--%3E%20Q%7B%22%E5%8F%96%E5%80%BC%22%7D%0A%20%20Q%20--%3E%7C%22l%3D1%22%7C%20A%5B%22KV%20%E9%A2%84%E7%AE%97%20%3D%20%E7%BA%AF%20Transformer%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%AD%E7%AD%89%20(%E5%A6%82%204-8)%22%7C%20B%5B%22KV%20%E7%BC%A9%E5%88%B0%201%2Fl%20%C2%B7%20%E4%BF%9D%E7%95%99%E7%B2%BE%E7%A1%AE%E6%A3%80%E7%B4%A2%22%5D%0A%20%20Q%20--%3E%7C%22l%20%E6%8E%A5%E8%BF%91%20L%22%7C%20C%5B%22%E5%87%A0%E4%B9%8E%E7%BA%AF%20Mamba%20%C2%B7%20%E6%A3%80%E7%B4%A2%E7%B2%BE%E5%BA%A6%E5%8F%97%E6%8D%9F%22%5D%0A%20%20A%20--%3E%20EXP%5B%22%E8%B4%B5%3A%20%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E7%BC%93%E5%AD%98%E6%89%93%E7%88%86%22%5D%0A%20%20B%20--%3E%20SWEET%5B%22%E5%8F%AF%E9%83%A8%E7%BD%B2%E7%9A%84%E4%B8%AD%E9%97%B4%E7%82%B9%22%5D%0A%20%20C%20--%3E%20CHEAP%5B%22%E4%BE%BF%E5%AE%9C%E4%BD%86%20in-context%20%E5%8F%98%E5%BC%B1%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字实例：把 \\(1/l\\) 代进去看——纯 Transformer 每层都存 KV，\\(l=8\\) 时只有约八分之一的层存 KV，同样 100 万 token 的上下文，缓存账单直接降到约 12.5%。这就是「注意力间隔决定 KV 预算」的具体含义：间隔每放大一倍，缓存省一半，但能做精确对齐的层也少一半。</span></p><p>Mamba 层则在两次注意力之间做线性扫描，把局部模式和可压缩的长程统计写进 SSM 状态。下一层注意力看到的残差，已经过 SSM 的混合，不完全是原始 token 流。于是注意力不必在每一层重复同一份全局匹配。</p><p><span class="marginnote">KV 只在注意力层物化。Mamba 层的状态宽度与上下文长度无关，不进入 KV 预算。</span></p><h3 id="moe-叠在混合骨架上" tabindex="-1">MoE 叠在混合骨架上 <a class="header-anchor" href="#moe-叠在混合骨架上" aria-label="Permalink to &quot;MoE 叠在混合骨架上&quot;">​</a></h3><p>Jamba 的总参数可以很大（专家数 × 专家宽），激活参数保持在较小的一档。这与 Switch Transformer 一类的稀疏前馈相同，只是底座从纯 Transformer 换成了 Mamba–注意力交错。负载均衡、专家并行、路由抖动，全部是 MoE 自己的工程，不因下面是 SSM 而消失。混合架构若在路由上失败，表现会先像一个坏 MoE，而不是像一个坏 SSM。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交错比是超参，对任务敏感。检索型、needle-in-haystack、严格的 in-context 拷贝，需要更密的注意力；纯长文档的流畅续写，可以更稀。没有一条对所有下游都最优的 \\(l\\)。把 Jamba 理解成「Mamba 已经足够、注意力只是遗留」会读反论文：注意力被留下，正是因为 SSM 单独不够。层比一旦在预训练里钉死，推理期很难再加密注意力而不重新训练，所以 \\(l\\) 是产品决策，不是运行时开关。</p><p><span class="marginnote">常见误区：初学者容易以为「层比是推理配置，负载重就把注意力调密一点」。实际上 \\(l\\) 与 \\(e\\) 在预训练时就浇筑进了权重——Mamba 层从没学过「等后面的注意力来兜底」之外的全球匹配方式，推理期改交错比等于让没受过训的结构上网，效果会崩而不是变强。</span></p><p>实现上，两种层的 kernel 不同，编译、量化、投机解码都要走两套。训练时的流水线切分也更烦：注意力层通信 KV，Mamba 层通信状态。MoE 再引入专家并行，三套并行维度（数据、专家、序列核）必须一起排。这是部署成本，不是论文图表里的曲线。</p><p><span class="marginnote">Jamba 1.5 等后续版本改宽度、改对齐数据，不改变「注意力–Mamba–MoE」这张图。本篇只讨论这张图。</span></p><p>与 Griffin 的差别要写清：Griffin 的注意力是局部窗口、全局通道是线性 RNN，且可以没有 MoE；Jamba 的注意力是全局的、全局通道由注意力与 Mamba 共同承担，并用 MoE 堆参数。两者都是混合，混合的轴不一样。部署时若只报告总参数或只报告激活参数，会把 MoE 的稀疏与 SSM 的线性时间混成一个「效率」数字；正确的报表是三栏——注意力层 KV、\\(l\\) 与 \\(e\\)、激活 FLOP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Jamba（Lieber 等，AI21，2024）把 Transformer 注意力层与 Mamba 层按周期交错，并在部分前馈上使用 MoE：用少数全序列注意力保住检索与 in-context，用多数选择性 SSM 压低长上下文的时间与 KV，用专家稀疏放大容量。它是层间混合的工程解，不是新的序列算子。读它时应盯住两个周期——注意力间隔 \\(l\\) 与 MoE 间隔 \\(e\\)——以及由此而来的 KV 预算，而不是把它简化成「带 MoE 的 Mamba」。交错比在预训练里钉死之后，几乎不能当推理开关用。</p>',13))])}const u=i(M,[["render",B]]);export{D as __pageData,u as default};
